function ApplicationDetails({app,questions}){return <div className="answerDetail"><div className="detailGrid"><p><b>الاسم:</b> {app.name||'—'}</p><p><b>Discord ID:</b> {app.discordId}</p><p><b>الدفعة:</b> {app.batchId}</p><p><b>التاريخ:</b> {fmt(app.submittedAt)}</p><p><b>الحالة:</b> {statusName(app.status)}</p><p><b>المراجع:</b> {app.reviewerName||'—'}</p></div><h4>الإجابات</h4>{questions.map((q,i)=><div className="answerCard" key={q.id}><strong>{i+1}. {q.text}</strong><span>{String(app.answers?.[q.id]??'—')}</span></div>)}<h4>سجل المراجعة</h4>{(app.history||[]).map((h,i)=><div className="historyList" key={i}>{statusName(h.status)} · {fmt(h.at)} · {h.reviewerName||'—'}{h.note?` · ${h.note}`:''}</div>)}</div>}
