function accessName(a){return a==='all'?'الجميع':a==='police'?'الشرطة فقط':a==='link'?'بالرابط فقط':'أشخاص محددون'}
const examAnswerStats=(result,exam)=>{const qs=Array.isArray(exam?.questions)?exam.questions:[],answers=result?.answers&&typeof result.answers==='object'?result.answers:{};let correct=0,wrong=0,unanswered=0,answered=0;for(const q of qs){const a=String(answers[q.id]??'').trim();if(a)answered++;else unanswered++;if(q.type==='choice'||q.type==='yesno'){if(a&&a===String(q.correct??''))correct++;else if(a)wrong++;}}return{total:qs.length,answered,correct,wrong,unanswered};};function typeName(t){return t==='choice'?'اختيارات':t==='yesno'?'نعم / لا':'إجابة نصية'}
function ExamAnswers({result,exam,close}){const s=examAnswerStats(result,exam);return <div className="modalBackdrop" onClick={close}><div className="modalCard examAnswersModal" onClick={e=>e.stopPropagation()}><div className="panelHead"><div><h2>مراجعة إجابات المتقدم</h2><p>{result.name||result.userId} · Discord ID: {result.userId}</p></div><Btn onClick={close}>إغلاق</Btn></div><div className="examReviewStats"><span>النتيجة <b>{result.score}%</b></span><span>أجاب <b>{s.answered}/{s.total}</b></span><span className="correctStat">صح <b>{s.correct}</b></span><span className="wrongStat">غلط <b>{s.wrong}</b></span><span>بدون إجابة <b>{s.unanswered}</b></span><span>مدة الاختبار <b>{Math.floor((result.durationSeconds||0)/60)} د {(result.durationSeconds||0)%60} ث</b></span></div>{(exam.questions||[]).map((q,i)=>{const answer=String(result.answers?.[q.id]??'').trim(),gradable=q.type==='choice'||q.type==='yesno',correct=gradable&&answer===String(q.correct??'');return <div className={`answerCard ${gradable?(correct?'answerCorrect':'answerWrong'):''}`} key={q.id}><strong>{i+1}. {q.text}</strong><span><b>إجابة المتقدم:</b> {answer||'لم تتم الإجابة'}</span>{gradable&&<span><b>الإجابة الصحيحة:</b> {q.correct||'—'}</span>}{!gradable&&<span><b>التقييم:</b> إجابة نصية — تحتاج مراجعة يدوية</span>}</div>})}</div></div>}function ExamEditor({exam,setExam,bank,save,cancel}){const patch=p=>setExam({...exam,...p}),usedBankIds=new Set((exam.questions||[]).map(q=>String(q.questionBankId||''))),availableBank=bank.filter(q=>!usedBankIds.has(String(q.id))),addQuestion=q=>patch({questions:[...(exam.questions||[]),cloneQuestion(q)]}),[bankOpen,setBankOpen]=useState(false);return <div className="panel examEditor"><div className="panelHead"><div><h2>{exam.id?'تعديل الاختبار':'إنشاء اختبار جديد'}</h2><p className="muted">غيّر الإعدادات هنا وسيبقى الاختبار بنفس الـID.</p></div><Btn onClick={cancel}>إلغاء</Btn></div><div className="formGrid"><input value={exam.title} onChange={e=>patch({title:e.target.value})} placeholder="عنوان الاختبار"/><input value={exam.description} onChange={e=>patch({description:e.target.value})} placeholder="الوصف"/><input value={exam.stage} onChange={e=>patch({stage:e.target.value})} placeholder="المرحلة"/><input type="number" min="1" max="100" value={exam.passingScore} onChange={e=>patch({passingScore:Number(e.target.value)})} placeholder="درجة النجاح"/><input type="number" min="1" value={exam.durationMinutes} onChange={e=>patch({durationMinutes:Number(e.target.value)})} placeholder="المدة بالدقائق"/><input type="number" min="1" value={exam.attemptsAllowed||1} onChange={e=>patch({attemptsAllowed:Number(e.target.value)})} placeholder="المحاولات"/><input type="datetime-local" value={localDateTimeInput(exam.startAt)} onChange={e=>patch({startAt:e.target.value})}/><input type="datetime-local" value={localDateTimeInput(exam.endAt)} onChange={e=>patch({endAt:e.target.value})}/></div><div className="panel" style={{marginTop:12}}><h3>من يمكنه دخول الاختبار؟</h3><div className="options">{[['all','الجميع'],['police','الشرطة فقط'],['link','بالرابط فقط'],['specific','أشخاص محددون']].map(([v,l])=><label key={v}><input type="radio" name={`access-${exam.id||'new'}`} checked={exam.accessType===v} onChange={()=>patch({accessType:v,accessToken:v==='link'?(exam.accessToken||''):''})}/><span>{l}</span></label>)}</div>{exam.accessType==='specific'&&<SpecificUsers exam={exam} patch={patch}/>} {exam.accessType==='link'&&<div className="linkBox"><label>رابط الاختبار الخاص</label>{exam.id&&exam.accessToken?<div className="rowActions"><input readOnly value={`${location.origin}/academy/exams?exam=${encodeURIComponent(exam.id)}&token=${encodeURIComponent(exam.accessToken)}`}/><Btn onClick={()=>navigator.clipboard?.writeText(`${location.origin}/academy/exams?exam=${encodeURIComponent(exam.id)}&token=${encodeURIComponent(exam.accessToken)}`)}><Copy size={14}/> نسخ</Btn></div>:<p className="muted">احفظ الاختبار أولًا؛ سيتم إنشاء الرابط تلقائيًا.</p>}</div>}</div><label className="switchLine"><input type="checkbox" checked={exam.active!==false} onChange={e=>patch({active:e.target.checked})}/> الاختبار مفعل</label><div className="bankToolbar"><h3>أسئلة الاختبار</h3><Btn onClick={()=>setBankOpen(!bankOpen)}><BookOpen size={15}/> إضافة من فهرس الأسئلة</Btn></div>{bankOpen&&<div className="bankPicker">{availableBank.map(q=><div className="bankPickRow" key={q.id}><div><strong>{q.text}</strong><small>{typeName(q.type)} · الصحيحة: {q.correct||'—'}</small></div><Btn onClick={()=>addQuestion(q)}>إضافة</Btn></div>)}{!availableBank.length&&<div className="emptyMini">لا توجد أسئلة متاحة من الفهرس لهذا الاختبار.</div>}</div>}{(exam.questions||[]).map((q,i)=><div key={q.id} className="examQuestionWrap"><QuestionEditor question={q} onChange={v=>patch({questions:exam.questions.map((x,j)=>j===i?normalizeQuestion(v):x)})}/><Btn className="danger" onClick={()=>patch({questions:exam.questions.filter((_,j)=>j!==i)})}><Trash2 size={14}/> حذف من الاختبار</Btn></div>)}<Btn onClick={()=>addQuestion({text:'سؤال جديد',type:'choice',options:['اختيار 1','اختيار 2'],correct:'',required:true,points:1})}><Plus size={15}/> سؤال جديد</Btn><br/><Btn className="primary" onClick={save}><Save size={16}/> حفظ الاختبار</Btn></div>}
function SpecificUsers({exam,patch}){const[id,setId]=useState('');const add=()=>{const x=id.replace(/\D/g,'');if(!x)return;patch({allowedDiscordIds:[...new Set([...(exam.allowedDiscordIds||[]),x])]});setId('')};return <div className="questionChoices"><label>Discord IDs المسموح لهم</label><div className="rowActions"><input value={id} onChange={e=>setId(e.target.value)} placeholder="Discord ID"/><Btn onClick={add}><Plus size={14}/> إضافة</Btn></div>{(exam.allowedDiscordIds||[]).map(x=><div className="applicationRow compactRow" key={x}><span>{x}</span><button className="danger" onClick={()=>patch({allowedDiscordIds:exam.allowedDiscordIds.filter(v=>v!==x)})}><Trash2 size={14}/></button></div>)}</div>}
function QuestionEditor({question,onChange,onDelete,collapsed=false,onToggleCollapse}){const patch=p=>onChange({...question,...p});const opts=question.options||[];return <div className={`panel questionAdmin ${collapsed?'questionCollapsed':''}`}><div className="questionAdminHeader"><div className="questionAdminTitle"><span>{question.text||'سؤال بدون نص'}</span><small>{question.type==='choice'?'اختيارات':question.type==='yesno'?'نعم / لا':'إجابة نصية'} · {question.points||1} درجة</small></div>{onToggleCollapse&&<Btn onClick={onToggleCollapse}>{collapsed?'فتح':'طي'} <span aria-hidden="true">{collapsed?'⌄':'⌃'}</span></Btn>}</div>{!collapsed&&<><div className="formGrid"><textarea value={question.text} onChange={e=>patch({text:e.target.value})} placeholder="نص السؤال"/><select value={question.type} onChange={e=>patch({type:e.target.value,options:e.target.value==='choice'?(opts.length?opts:['اختيار 1','اختيار 2']):[],correct:''})}><option value="choice">اختيارات</option><option value="yesno">نعم / لا</option><option value="text">إجابة نصية</option></select><input type="number" min="1" value={question.points||1} onChange={e=>patch({points:Number(e.target.value)})} placeholder="الدرجة"/></div>{question.type==='choice'&&<div className="questionChoices">{opts.map((o,i)=><div className="choiceEditor" key={i}><input value={o} onChange={e=>patch({options:opts.map((x,j)=>j===i?e.target.value:x),correct:question.correct===o?e.target.value:question.correct})}/><button type="button" className="danger" onClick={()=>patch({options:opts.filter((_,j)=>j!==i),correct:question.correct===o?'':question.correct})}><Trash2 size={14}/></button></div>)}<Btn onClick={()=>patch({options:[...opts,`اختيار ${opts.length+1}`]})}><Plus size={14}/> اختيار</Btn><select value={question.correct||''} onChange={e=>patch({correct:e.target.value})}><option value="">الإجابة الصحيحة</option>{opts.map((o,i)=><option key={i} value={o}>{o}</option>)}</select></div>}{question.type==='yesno'&&<select value={question.correct||''} onChange={e=>patch({correct:e.target.value})}><option value="">الإجابة الصحيحة</option><option value="نعم">نعم</option><option value="لا">لا</option></select>}<label className="checkItem"><input type="checkbox" checked={question.required!==false} onChange={e=>patch({required:e.target.checked})}/> مطلوب</label>{onDelete&&<div className="questionAdminActions"><button type="button" className="danger" onClick={onDelete}><Trash2 size={14}/> حذف السؤال بالكامل</button></div>}</>}</div>}
function QuestionBankAdmin({state,reload,setMsg}){const[questions,setQuestions]=useState((state.questionBank||[]).map(normalizeQuestion)),[search,setSearch]=useState(''),[editing,setEditing]=useState(null);useEffect(()=>setQuestions((state.questionBank||[]).map(normalizeQuestion)),[state.questionBank]);const save=async()=>{try{await api('/api/admin/question-bank',{method:'PUT',body:JSON.stringify({questions})});setEditing(null);setMsg('تم حفظ فهرس الأسئلة.');reload()}catch(e){setMsg(errText(e))}};const filtered=questions.filter(q=>q.text.toLowerCase().includes(search.toLowerCase()));return <div className="adminSection"><div className="panel"><div className="panelHead"><div><h2>فهرس الأسئلة</h2><p className="muted">مكتبة مركزية للأسئلة مع الاختيارات والإجابة الصحيحة. السؤال في الفهرس مستقل عن الاختبارات.</p></div><Btn className="primary" onClick={()=>setQuestions(a=>[...a,normalizeQuestion({text:'سؤال جديد',type:'choice',options:['اختيار 1','اختيار 2'],correct:'',required:true,points:1})])}><Plus size={16}/> إضافة سؤال للفهرس</Btn></div><div className="search"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="ابحث في الفهرس"/></div>{filtered.map(q=><div className="bankRow" key={q.id}><div><strong>{q.text||'سؤال بدون نص'}</strong><small>{typeName(q.type)} · {q.points||1} درجة · الصحيحة: <b>{q.correct||'غير محددة'}</b></small>{q.type==='choice'&&<small>الاختيارات: {(q.options||[]).join(' · ')}</small>}</div><div className="rowActions"><Btn onClick={()=>setEditing(q)}>تعديل</Btn><button className="danger" onClick={()=>setQuestions(a=>a.filter(x=>x.id!==q.id))}><Trash2 size={14}/></button></div></div>)}{!filtered.length&&<div className="emptyMini">لا توجد أسئلة.</div>}<Btn className="primary" onClick={save}><Save size={16}/> حفظ الفهرس</Btn></div>{editing&&<div className="panel"><div className="panelHead"><h2>تعديل سؤال</h2><Btn onClick={()=>setEditing(null)}>إلغاء</Btn></div><QuestionEditor question={editing} onChange={v=>{const n=normalizeQuestion(v);setEditing(n);setQuestions(a=>a.map(q=>q.id===n.id?n:q))}}/><Btn className="primary" onClick={save}><Save size={16}/> حفظ</Btn></div>}</div>}
function MembersAdmin({state,reload,setMsg}){
  const[q,setQ]=useState('');
  const[saving,setSaving]=useState('');
  const[urls,setUrls]=useState({});
  const[view,setView]=useState('cards');
  const list=(state.members||[]).filter(m=>`${m.name||''} ${m.rank||''} ${m.discordId||''} ${m.badge||''} ${m.responsibility||''}`.toLowerCase().includes(q.trim().toLowerCase()));

  const fileToDataUrl=async file=>{
    if(!/^image\/(png|jpeg|webp)$/i.test(file.type)) throw Error('PNG أو JPG/JPEG أو WebP فقط.');
    const src=URL.createObjectURL(file);
    try{
      const img=new Image();
      await new Promise((ok,no)=>{img.onload=ok;img.onerror=()=>no(Error('تعذر قراءة الصورة.'));img.src=src});
      let w=img.naturalWidth,h=img.naturalHeight,max=1200;
      if(w>max||h>max){const scale=Math.min(max/w,max/h);w=Math.max(1,Math.round(w*scale));h=Math.max(1,Math.round(h*scale))}
      const canvas=document.createElement('canvas');let quality=.86,out='';
      for(let n=0;n<8;n++){canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d');if(!ctx)throw Error('تعذر تجهيز الصورة.');ctx.clearRect(0,0,w,h);ctx.drawImage(img,0,0,w,h);out=canvas.toDataURL('image/webp',quality);if(out.length<=170000)break;quality*=.82;w=Math.max(320,Math.round(w*.9));h=Math.max(320,Math.round(h*.9))}
      return out;
    }finally{URL.revokeObjectURL(src)}
  };
  const saveImage=async(m,image)=>{setSaving(m.discordId);try{await api('/api/admin/member-image',{method:'POST',body:JSON.stringify({discordId:m.discordId,image})});setMsg('تم حفظ صورة الفرد.');setUrls(v=>({...v,[m.discordId]:''}));reload()}catch(x){setMsg(errText(x))}finally{setSaving('')}};
  const upload=async(m,file)=>{if(!file)return;try{setMsg('جارٍ تجهيز الصورة...');await saveImage(m,await fileToDataUrl(file))}catch(x){setMsg(x.message||String(x))}};
  const setUrl=async m=>{const url=String(urls[m.discordId]||'').trim();let parsed;try{parsed=new URL(url)}catch{return setMsg('ضع رابط صورة صحيح يبدأ بـ https:// أو http://.')}if(!['http:','https:'].includes(parsed.protocol))return setMsg('ضع رابط صورة مباشر يبدأ بـ https:// أو http://.');await saveImage(m,url)};
  const removeImage=async m=>{if(!m.image)return;if(!confirm(`حذف صورة «${m.name||m.discordId}» من الموقع؟`))return;setSaving(m.discordId);try{await api('/api/admin/member-image',{method:'DELETE',body:JSON.stringify({discordId:m.discordId})});setMsg('تم حذف الصورة.');reload()}catch(x){setMsg(errText(x))}finally{setSaving('')}};
  const drop=(m,e)=>{e.preventDefault();const file=e.dataTransfer?.files?.[0];if(file)upload(m,file)};
  const imageControls=m=><div className="memberImagePanel">
    <div className="memberImagePanelTitle"><Upload size={15}/> صورة الفرد</div>
    <div className="memberImageActions">
      <label className="upload memberDrop" onDragOver={e=>e.preventDefault()} onDrop={e=>drop(m,e)}><Upload size={14}/>{saving===m.discordId?'جارٍ الحفظ...':'رفع صورة'}<input type="file" accept="image/png,image/jpeg,image/webp" disabled={saving===m.discordId} onChange={e=>upload(m,e.target.files?.[0])}/></label>
      <div className="imageUrlRow"><input value={urls[m.discordId]||''} onChange={e=>setUrls(v=>({...v,[m.discordId]:e.target.value}))} placeholder="أو الصق رابط الصورة المباشر"/><button className="secondary" disabled={saving===m.discordId} onClick={()=>setUrl(m)}>حفظ الرابط</button></div>
      {m.image&&<button className="danger memberDeleteImage" disabled={saving===m.discordId} onClick={()=>removeImage(m)}><Trash2 size={14}/> حذف</button>}
    </div>
  </div>;
  const identity=m=><div className="adminMemberIdentity">
    <div className="memberAvatar adminMemberAvatar">{m.image?<img src={m.image} alt=""/>:<Users size={22}/>}</div>
    <div className="adminMemberMain">
      <div className="adminMemberNameRow"><strong>{m.name||'بدون اسم'}</strong><span className="memberPresenceDot" title="الفرد مسجل في سجل الشرطة"/></div>
      <div className="adminMemberBadges"><span className="memberChip memberChipRank">{m.rank||'بدون رتبة'}</span><span className="memberChip">{m.badge||'بدون Badge'}</span></div>
      <small className="adminMemberDiscord">Discord ID: {m.discordId}</small>
    </div>
  </div>;
  return <div className="panel membersAdminPanel">
    <div className="membersToolbar"><div><span className="eyebrow">ACADEMY PERSONNEL</span><h2>إدارة الأفراد</h2><p className="muted">بيانات الأفراد الأساسية والرتب تُسحب مباشرة من سجل الشرطة. الإدارة هنا مخصصة للعرض وإدارة صورة الملف.</p></div><div className="membersCount"><b>{list.length}</b><span>إجمالي النتائج</span></div></div>
    <div className="membersControls">
      <div className="search membersSearch"><Search size={17}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="ابحث بالاسم أو الرتبة أو Badge أو Discord ID"/></div>
      <div className="membersViewSwitch" aria-label="طريقة عرض الأفراد">
        <button type="button" className={view==='cards'?'active':''} onClick={()=>setView('cards')}><Users size={15}/> بطاقات</button>
        <button type="button" className={view==='list'?'active':''} onClick={()=>setView('list')}><FileText size={15}/> قائمة</button>
        <button type="button" className={view==='compact'?'active':''} onClick={()=>setView('compact')}><Network size={15}/> مختصرة</button>
      </div>
    </div>
    <div className={view==='cards'?'adminMembersGrid adminMembersCards':view==='list'?'adminMembersGrid adminMembersList':'adminMembersGrid adminMembersCompact'}>
      {list.map(m=><article className="adminMemberCard" key={m.discordId}>
        {identity(m)}
        <div className="adminMemberMeta"><div><span>المسؤولية</span><strong>{m.responsibility||'غير محددة'}</strong></div><div><span>مصدر البيانات</span><strong>سجل الشرطة</strong></div></div>
        {imageControls(m)}
      </article>)}
    </div>
    {!list.length&&<div className="emptyMini membersEmpty">لا توجد نتائج مطابقة للبحث.</div>}
  </div>;
}
function AdminsAdmin({state,reload,setMsg}){
  const blank={discordId:'',name:'',permissions:['view_dashboard'],enabled:true};
  const[form,setForm]=useState(blank),[editing,setEditing]=useState(null);
  const all=[
    ['view_dashboard','لوحة الإدارة','الوصول الأساسي للوحة الإدارة'],
    ['view_activity_logs','السجلات الأمنية','سجل النشاط الإداري وتسجيلات الدخول'],
    ['manage_members','إدارة الأفراد','الأفراد والصور وملفاتهم الإدارية'],
    ['manage_roles','إدارة الرتب','إدارة الرتب والصلاحيات المرتبطة بها'],
    ['manage_admins','إدارة الأدمن','إضافة وتعديل وتعطيل الأدمن'],
    ['manage_applications','إدارة التقديمات','الدفعات والطلبات والمراجعات'],
    ['manage_exams','إدارة الاختبارات','الاختبارات والمحاولات والنتائج'],
    ['manage_hierarchy','إدارة الهيكل','هيكل الأكاديمية والمناصب'],
    ['view_evaluations','الاطلاع على التقييمات','قراءة التقارير السرية فقط'],
    ['manage_evaluations','إدارة التقييمات','مراجعة واعتماد ورفض وتحويل التقارير'],
    ['manage_settings','الإعدادات','إعدادات النظام الحساسة']
  ];
  const allKeys=all.map(x=>x[0]);
  const setPermissions=permissions=>setForm(f=>({...f,permissions}));
  const togglePermission=p=>setPermissions(form.permissions.includes(p)?form.permissions.filter(x=>x!==p):[...form.permissions,p]);
  const save=async()=>{if(!form.discordId.trim())return setMsg('أدخل Discord ID.');try{await api('/api/admin/admins',{method:'POST',body:JSON.stringify(form)});setMsg(editing?'تم تحديث صلاحيات الأدمن.':'تمت إضافة الأدمن.');setForm(blank);setEditing(null);reload()}catch(e){setMsg(errText(e))}};
  const edit=a=>{setEditing(a);setForm({discordId:a.discordId,name:a.name||'',permissions:a.permissions||[],enabled:a.enabled!==false})};
  const preset=(name)=>{if(name==='full')setPermissions(allKeys);else if(name==='none')setPermissions([]);else setPermissions(['view_dashboard','manage_applications','manage_exams','manage_members','view_evaluations'])};
  const selected=form.permissions.length;
  return <div className="adminSection">
    <div className="panel adminPermissionsPanel">
      <div className="panelHead adminPermissionsHead"><div><span className="eyebrow">ACCESS CONTROL</span><h2>{editing?'تعديل صلاحيات الأدمن':'إضافة أدمن'}</h2><p className="muted">الصلاحيات مستقلة. تفعيل صلاحية لا يمنح الأدمن تلقائيًا صلاحيات السجلات أو التقييمات السرية.</p></div><span className="permissionCounter">{selected}/{all.length} صلاحية</span></div>
      <div className="permissionPresets"><button type="button" className="permissionPreset primary" onClick={()=>preset('full')}><Shield size={16}/> مدير كامل <small>كل الصلاحيات</small></button><button type="button" className="permissionPreset secondary" onClick={()=>preset('none')}><LockKeyhole size={16}/> بدون صلاحيات <small>اختيار يدوي</small></button><button type="button" className="permissionPreset secondary" onClick={()=>preset('standard')}><UserCog size={16}/> إدارة تشغيلية <small>الصلاحيات الأساسية</small></button></div>
      <div className="permissionToolbar"><span>الصلاحيات المتاحة</span><div><button type="button" onClick={()=>setPermissions(allKeys)}>تحديد الكل</button><button type="button" onClick={()=>setPermissions([])}>إلغاء الكل</button></div></div>
      <div className="formGrid adminIdentityFields"><input value={form.discordId} disabled={Boolean(editing)} onChange={e=>setForm({...form,discordId:e.target.value})} placeholder="Discord ID"/><input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="اسم الأدمن"/></div>
      <div className="permissionGrid permissionGridEnhanced">{all.map(([p,l,d])=><label className={'permissionCard '+(form.permissions.includes(p)?'selected':'')} key={p}><input type="checkbox" checked={form.permissions.includes(p)} onChange={()=>togglePermission(p)}/><span><b>{l}</b><small>{d}</small></span><i>{form.permissions.includes(p)?'مفعلة':'غير مفعلة'}</i></label>)}</div>
      <div className="rowActions"><Btn className="primary" onClick={save}><Save size={16}/> {editing?'حفظ التعديلات':'إضافة أدمن'}</Btn>{editing&&<Btn onClick={()=>{setEditing(null);setForm(blank)}}>إلغاء</Btn>}</div>
    </div>
    <div className="adminListGrid">{(state.admins||[]).map(a=><div className="panel adminAccountCard" key={a.discordId}><div className="panelHead"><div className="adminAccountIdentity"><div className="adminAccountAvatar"><UserRound size={20}/></div><div><b>{a.name||'بدون اسم'}</b><small>Discord ID: {a.discordId}</small></div></div><span className={a.enabled===false?'closedBadge':'ok'}>{a.enabled===false?'معطل':'مفعل'}</span></div><div className="adminAccountMeta"><span>{(a.permissions||[]).length} صلاحية مفعلة</span><span>{a.source==='environment'?'أدمن بيئي محمي':'أدمن قابل للتعديل'}</span></div>{a.source!=='environment'&&<div className="rowActions"><Btn onClick={()=>edit(a)}>تعديل الصلاحيات</Btn><Btn onClick={async()=>{await api(`/api/admin/admins/${a.discordId}`,{method:'PATCH',body:JSON.stringify({enabled:!a.enabled})});reload()}}><Power size={14}/> {a.enabled===false?'تفعيل':'تعطيل'}</Btn><button className="danger" onClick={async()=>{if(confirm('حذف الأدمن؟')){await api(`/api/admin/admins/${a.discordId}`,{method:'DELETE'});reload()}}}><Trash2 size={14}/> حذف</button></div>}</div>)}</div>
  </div>;
}
function HierarchyAdmin({state,reload,setMsg}){const seed=(state.hierarchy||[]).map((x,i)=>({...x,level:Number(x.level)||Math.max(1,Math.ceil((Math.sqrt(8*(i+1)+1)-1)/2)),position:Number(x.position||x.order)||i+1}));const[items,setItems]=useState(seed);useEffect(()=>setItems((state.hierarchy||[]).map((x,i)=>({...x,level:Number(x.level)||Math.max(1,Math.ceil((Math.sqrt(8*(i+1)+1)-1)/2)),position:Number(x.position||x.order)||i+1}))),[state.hierarchy]);const patch=(idv,k,v)=>setItems(a=>a.map(x=>String(x.id)===String(idv)?{...x,[k]:k==='level'||k==='position'?Math.max(1,Number(v)||1):v}:x));const add=()=>setItems(a=>[...a,{id:`node-${Date.now()}`,title:'منصب جديد',name:'غير محدد',discordId:'',image:'',level:1,position:1}]);const remove=idv=>setItems(a=>a.filter(x=>String(x.id)!==String(idv)));const sortedItems=[...items].sort((a,b)=>Number(a.level)-Number(b.level)||Number(a.position)-Number(b.position));const normalize=()=>{const sorted=[...items].sort((a,b)=>Number(a.level)-Number(b.level)||Number(a.position)-Number(b.position));const counts={};return sorted.map(x=>{const level=Math.max(1,Number(x.level)||1);counts[level]=(counts[level]||0)+1;return {...x,level,position:counts[level]}})};const save=async()=>{try{const normalized=normalize();setItems(normalized);await api('/api/admin/hierarchy',{method:'POST',body:JSON.stringify({items:normalized})});setMsg('تم حفظ الهيكل. المستوى يحدد الصف والموقع يحدد ترتيب البطاقة داخله.');reload()}catch(e){setMsg(errText(e))}};return <div className="panel hierarchyAdminPanel"><div className="panelHead"><div><span className="eyebrow">ACADEMY ORGANIZATION</span><h2>هيكل الأكاديمية</h2><p className="muted">التنظيم بسيط: <b>المستوى = الصف</b> و<b>الموقع = ترتيب الشخص داخل الصف</b>. مثال: 1-1 في الصف الأول، و2-1 و2-2 في الصف الثاني.</p></div><div className="rowActions"><Btn onClick={add}><Plus size={15}/> إضافة منصب</Btn><Btn className="primary" onClick={save}><Save size={15}/> حفظ الهيكل</Btn></div></div><div className="hierarchyAdminLegend"><span><b>المستوى</b> = الصف</span><span><b>الموقع</b> = ترتيب البطاقة</span><span>مثال: <b>3-2</b> = الصف 3، البطاقة 2</span></div>{sortedItems.map((x)=><div className="hierEdit hierarchyEditCard" key={x.id}><div className="preview">{x.image?<img src={x.image} alt=""/>:<Network/>}<small>{x.level}-{x.position}</small></div><div className="editFields hierarchyEditFields"><label>المنصب<input value={x.title||''} onChange={e=>patch(x.id,'title',e.target.value)} placeholder="المنصب"/></label><label>الاسم<input value={x.name||''} onChange={e=>patch(x.id,'name',e.target.value)} placeholder="الاسم"/></label><label>Discord ID<input value={x.discordId||''} onChange={e=>patch(x.id,'discordId',e.target.value)} placeholder="Discord ID"/></label><label>رابط الصورة<input value={x.image||''} onChange={e=>patch(x.id,'image',e.target.value)} placeholder="رابط الصورة"/></label><label>المستوى<input type="number" min="1" value={x.level||1} onChange={e=>patch(x.id,'level',e.target.value)}/></label><label>الموقع<input type="number" min="1" value={x.position||1} onChange={e=>patch(x.id,'position',e.target.value)}/></label></div><button className="danger" title="حذف من الهيكل" onClick={()=>remove(x.id)}><Trash2 size={15}/> حذف</button></div>)}{!items.length&&<div className="emptyMini">لا توجد مناصب حاليًا. أضف أول منصب إلى الهيكل.</div>}</div>}
function EvaluationsAdmin({state,reload,setMsg}){const[status,setStatus]=useState('all');
const remove=async id=>{if(!confirm('حذف التقييم؟'))return;try{await api('/api/admin/evaluations/'+id,{method:'DELETE'});reload()}catch(e){setMsg(errText(e))}};
const review=async(e,nextStatus)=>{const note=window.prompt('ملاحظة المراجعة (اختياري):')??'';try{await api('/api/admin/evaluations/'+e.id+'/review',{method:'PATCH',body:JSON.stringify({status:nextStatus,note})});setMsg('تم تحديث حالة التقرير.');reload()}catch(x){setMsg(errText(x))}};
const all=(state.evaluations||[]).filter(e=>status==='all'||e.status===status);const trainerReports=all.filter(e=>e.type==='trainer_to_trainee');const traineeReports=all.filter(e=>e.type==='trainee_to_trainer');
const statusLabel=s=>s==='approved'?'معتمد':s==='rejected'?'مرفوض':s==='investigation'?'تحقيق':'قيد المراجعة';const statusClass=s=>s==='approved'?'ok':s==='rejected'?'closedBadge':s==='investigation'?'danger':'openBadge';
const trainerFields=[['driving','مهارة القيادة'],['citizens','التعامل مع المواطنين والزملاء'],['devices','التعامل مع أجهزة الشرطة'],['calls','التعامل مع البلاغات'],['weapons','التعامل مع الأسلحة']];const traineeFields=[['trainingQuality','جودة التدريب وتنظيمه'],['explanation','وضوح الشرح ونقل المعلومات'],['communication','التعامل والتواصل مع المتدرب'],['fairness','العدل والالتزام في التقييم والتعامل'],['knowledge','الإلمام بالقوانين وإجراءات العمل'],['professionalism','الاحترافية والانضباط']];
const Card=({e,isTrainer})=><div className={'evaluationAdminCard evaluationAdminCard--'+(isTrainer?'trainer':'trainee')}><div className="evaluationAdminHead"><div className="evaluationPeople"><span className="evaluationTypeBadge">{isTrainer?'تقرير مدرب ← متدرب':'تقرير متدرب ← مدرب'}</span><h3>{isTrainer?'تقييم متدرب':'تقييم مدرب'}</h3><div className="evaluationRelation"><div><small>مقدّم التقرير</small><strong>{e.fromName||e.fromDiscordId}</strong><span>{e.fromRank||'—'} · Discord: {e.fromDiscordId||'—'}</span></div><b>→</b><div><small>الشخص المُقيَّم</small><strong>{e.targetName||e.targetDiscordId}</strong><span>{e.targetRank||'—'} · Discord: {e.targetDiscordId||'—'}</span></div></div></div><div className="evaluationAdminScore"><b>{Number(e.rating||e.overallRating||0)}/10</b><span className={statusClass(e.status)}>{statusLabel(e.status)}</span><small>{fmt(e.createdAt)}</small></div></div>
<div className="evaluationSummaryGrid"><div><strong>اتجاه التقييم</strong><span>{isTrainer?'المدرب يقيّم المتدرب':'المتدرب يقيّم المدرب'}</span></div>{isTrainer&&<div><strong>ساعات التدريب</strong><span>{e.hours||0} ساعة</span></div>}{!isTrainer&&<div><strong>نفس المدرب</strong><span>{e.sameTrainer?'نعم':'لا'}</span></div>}<div><strong>التقييم العام</strong><span>{Number(e.rating||e.overallRating||0)}/10</span></div></div>
<div className="evaluationRatingsReadOnly">{(isTrainer?trainerFields:traineeFields).map(([k,l])=><div key={k}><span>{l}</span><b>{e.ratings?.[k]||'—'}/10</b></div>)}</div>{e.notes&&<div className="statusNote evaluationNotes"><b>ملاحظات المقيّم:</b><p>{e.notes}</p></div>}{e.complaint&&<div className="complaintAdmin"><strong>⚠ شكوى / توضيح إضافي</strong><p>{e.complaint}</p><small>هذه الرسالة جزء من التقرير السري وليست تقييمًا منفصلًا.</small></div>}{e.review?.note&&<div className="statusNote evaluationReviewNote"><b>ملاحظة المراجع:</b><p>{e.review.note}</p></div>}
<div className="rowActions evaluationAdminActions"><Btn onClick={()=>review(e,'approved')}><Check size={14}/> اعتماد التقرير</Btn><Btn onClick={()=>review(e,'rejected')}>رفض التقرير</Btn><Btn className="danger" onClick={()=>review(e,'investigation')}>تحويل {isTrainer?'المتدرب':'المدرب'} للتحقيق</Btn><button className="danger" onClick={()=>remove(e.id)}><Trash2 size={14}/> حذف</button></div></div>;
return <div className="panel evaluationsAdminPanel"><div className="panelHead"><div><span className="eyebrow">CONFIDENTIAL EVALUATIONS</span><h2>مراجعة التقييمات والتقارير السرية</h2><p className="muted">كل نوع من التقييمات له نموذج مستقل، ويُعرض هنا بوضوح من قيّم من، وما هي الدرجات، وهل توجد شكوى أو توضيح.</p></div><span className="ok">{all.length} تقرير</span></div><div className="evaluationFilters">{[['all','الكل'],['pending','قيد المراجعة'],['approved','معتمد'],['rejected','مرفوض'],['investigation','تحقيق']].map(([v,l])=><Btn key={v} className={status===v?'primary':'secondary'} onClick={()=>setStatus(v)}>{l}</Btn>)}</div>
<section className="evaluationReportSection"><div className="evaluationReportSectionHead"><div><Star size={20}/><div><h3>تقارير المدربين عن المتدربين</h3><p>المدرب يقيّم المتدرب وفق مهارات القيادة والتعامل مع المواطنين والأجهزة والبلاغات والأسلحة.</p></div></div><span>{trainerReports.length}</span></div>{trainerReports.map(e=><Card key={e.id} e={e} isTrainer/>)}{!trainerReports.length&&<div className="emptyMini">لا توجد تقارير مدربين بهذا الفلتر.</div>}</section>
<section className="evaluationReportSection"><div className="evaluationReportSectionHead"><div><Users size={20}/><div><h3>تقارير المتدربين عن المدربين</h3><p>المتدرب يقيّم جودة التدريب والشرح والتواصل والعدل والإلمام بالقوانين والاحترافية.</p></div></div><span>{traineeReports.length}</span></div>{traineeReports.map(e=><Card key={e.id} e={e} isTrainer={false}/>)}{!traineeReports.length&&<div className="emptyMini">لا توجد تقارير متدربين بهذا الفلتر.</div>}</section></div>}function SettingsAdmin({state,reload,setMsg}){const[s,setS]=useState({...state.settings});useEffect(()=>setS({...state.settings}),[state.settings]);const save=async()=>{try{await api('/api/admin/settings',{method:'PUT',body:JSON.stringify(s)});setMsg('تم حفظ الإعدادات.');reload()}catch(e){setMsg(errText(e))}};return <div className="panel settingsPanel"><h2>إعدادات النظام</h2><label>اسم الأكاديمية<input value={s.academyName||''} onChange={e=>setS({...s,academyName:e.target.value})}/></label><label>رابط الشعار<input value={s.logoUrl||''} onChange={e=>setS({...s,logoUrl:e.target.value})}/></label><label>عنوان التقديم<input value={s.applicationsTitle||''} onChange={e=>setS({...s,applicationsTitle:e.target.value})}/></label><label>وصف التقديم<textarea value={s.applicationsDescription||''} onChange={e=>setS({...s,applicationsDescription:e.target.value})}/></label><div className="settingsDivider"><h3>إعدادات رسائل التقديم</h3><p className="muted">يمكنك استخدام <b>{'{{batchName}}'}</b> داخل الرسالة ليتم استبداله تلقائيًا باسم الدفعة.</p><label>رسالة القبول<textarea value={s.acceptedMessage||''} onChange={e=>setS({...s,acceptedMessage:e.target.value})} placeholder="🎉 مبروك! تم قبولك في «{{batchName}}»\nالخطوة التالية..."/></label><label>رسالة الرفض<textarea value={s.rejectedMessage||''} onChange={e=>setS({...s,rejectedMessage:e.target.value})} placeholder="تم رفض طلبك في «{{batchName}}»\nنتمنى لك التوفيق..."/></label></div><div className="settingsDivider"><h3>صلاحيات التقييمات</h3><p className="muted">الرتب هنا تُسحب أصلًا من سجل الشرطة، ويمكنك فقط تحديد أي الرتب يسمح لها بالتقييم كمدرب أو كمتدرب.</p><div className="evalRankSettings"><div><h4>التقييم كمدرب</h4>{(state.members||[]).map(m=>m.rank).filter(Boolean).filter((v,i,x)=>x.indexOf(v)===i).map(r=><label className="checkItem" key={'tr-'+r}><input type="checkbox" checked={(s.evaluationTrainerRanks||[]).includes(r)} onChange={()=>setS({...s,evaluationTrainerRanks:(s.evaluationTrainerRanks||[]).includes(r)?s.evaluationTrainerRanks.filter(x=>x!==r):[...(s.evaluationTrainerRanks||[]),r]})}/>{r}</label>)}</div><div><h4>التقييم كمتدرب</h4>{(state.members||[]).map(m=>m.rank).filter(Boolean).filter((v,i,x)=>x.indexOf(v)===i).map(r=><label className="checkItem" key={'tt-'+r}><input type="checkbox" checked={(s.evaluationTraineeRanks||[]).includes(r)} onChange={()=>setS({...s,evaluationTraineeRanks:(s.evaluationTraineeRanks||[]).includes(r)?s.evaluationTraineeRanks.filter(x=>x!==r):[...(s.evaluationTraineeRanks||[]),r]})}/>{r}</label>)}</div></div></div><div className="settingsDivider"><h3>رابط الانضمام بعد القبول</h3><p className="muted">هذا الرابط يظهر للمتقدم المقبول ليتمكن من الانضمام إلى سيرفر الأكاديمية.</p></div><label>رابط Discord بعد القبول<input type="url" value={s.acceptedDiscordUrl||''} onChange={e=>setS({...s,acceptedDiscordUrl:e.target.value})} placeholder="https://discord.gg/su8PsTY5gJ"/></label><Btn className="primary" onClick={save}><Save size={16}/> حفظ الإعدادات</Btn></div>}